"""Render the historical comparison of two tacking assumptions."""
from statistics import median
import json
from simulate_tacking import ROOT,DATA
from validate_tacking import load_results


def main():
    runs=load_results();plan=json.loads((ROOT/'data/phase1/route-plan.json').read_text())
    labels={'ccw':'Gegen Uhrzeigersinn','cw':'Im Uhrzeigersinn'};models={'base':'Basis','cautious':'Vorsichtig'}
    lines=['# Umrundung mit Aufkreuzen: Basis und vorsichtiges Szenario','','Stand: 19.10.2026. Historische August–Oktober-Wetterdaten 2022–2025; Start an jedem Tag vom 1. August bis 30. September, Ende spätestens 31. Oktober. Wind **12–25 kn**, alle Windrichtungen grundsätzlich nutzbar. Gegenwind wird durch Kreuzschläge berücksichtigt, nicht durch direkte Fahrt gegen den Wind.','','**Keine vollständige Umrundung in den 976 Modellläufen.** Die Ergebnisse sind Rechnungen mit den vereinbarten Leistungsannahmen, keine Messung der Leistungsfähigkeit der Gruppe.','','## Auguststarts: Vergleich beider Richtungen','','| Modell | Richtung | Mindestens ein Fahrtag | Vollständige Runden | Fortschritt min. / Median / max. | Weitester Hotelort |','|---|---|---:|---:|---:|---|']
    for scenario,model in models.items():
        for direction,label in labels.items():
            rows=[r for r in runs if r['scenario']==scenario and r['direction']==direction and r['start'][5:7]=='08'];km=[r['completed_km'] for r in rows];best=max(rows,key=lambda r:r['completed_km'])
            lines.append(f"| {model} | {label} | {sum(r['riding_days']>0 for r in rows)}/124 | {sum(r['completed'] for r in rows)}/124 | {min(km):.1f} / {median(km):.1f} / {max(km):.1f} km | {plan['spots'][best['last_hotel']]['name']} |")
    lines+=['','Die Route umfasst rund 890,8 km. Fortschritt bezeichnet die Strecke entlang dieser Route; tatsächliche Fahrstrecken sind wegen Kreuzschlägen und Halsenkursen länger. 496 Augustläufe und ergänzend 480 Septemberläufe; überlappende Starttermine sind keine unabhängigen Wetterereignisse.','','In diesen Rechnungen erzielt die Richtung im Uhrzeigersinn in beiden Modellen sowohl den höheren Median als auch den grössten Fortschritt. Das ist eine Präferenz innerhalb dieses Modells, keine Garantie für eine reale Umrundung.','','## Auguststarts nach Wetterjahr','','| Jahr | Modell | Richtung | Fortschritt min. / Median / max. |','|---|---|---|---:|']
    for year in [2022,2023,2024,2025]:
        for scenario,model in models.items():
            for direction,label in labels.items():
                km=[r['completed_km'] for r in runs if r['year']==year and r['scenario']==scenario and r['direction']==direction and r['start'][5:7]=='08']
                lines.append(f'| {year} | {model} | {label} | {min(km):.1f} / {median(km):.1f} / {max(km):.1f} km |')
    lines+=['','## Vergleich: Septemberstarts','','| Modell | Richtung | Vollständige Runden | Fortschritt min. / Median / max. |','|---|---|---:|---:|']
    for scenario,model in models.items():
        for direction,label in labels.items():
            rows=[r for r in runs if r['scenario']==scenario and r['direction']==direction and r['start'][5:7]=='09'];km=[r['completed_km'] for r in rows]
            lines.append(f"| {model} | {label} | {sum(r['completed'] for r in rows)}/120 | {min(km):.1f} / {median(km):.1f} / {max(km):.1f} km |")
    lines+=['','## Weiteste Augustreise je Modell und Richtung','','Auswahl nach grösstem Fortschritt, bei Gleichstand erster Starttermin in der Ergebnisliste. Wartetage zählen bis 31. Oktober, auch nach dem letzten möglichen Fahrtag. Es handelt sich um abgebrochene Modellreisen, nicht um abgeschlossene Runden.','','| Modell | Richtung | Start | Fortschritt | Tatsächlich gefahren | Wasserzeit¹ | Fahrtage | Wartetage |','|---|---|---|---:|---:|---:|---:|---:|']
    best_runs=[]
    for scenario,model in models.items():
        for direction,label in labels.items():
            best=max((r for r in runs if r['scenario']==scenario and r['direction']==direction and r['start'][5:7]=='08'),key=lambda r:r['completed_km']);best_runs.append(best)
            lines.append(f"| {model} | {label} | {best['start']} | {best['completed_km']:.1f} km | {best['physical_km']:.1f} km | {best['water_hours']:.1f} h | {best['riding_days']} | {best['waiting_days']} |")
    lines+=['','¹ Einschliesslich der pauschalierten Manöververluste; ohne Landpausen. „Tatsächlich gefahren“ bezeichnet die geometrisch modellierte Fahrstrecke einschliesslich des bisherigen An-/Ablegezuschlags, keine GPS-Messung.']
    for r in best_runs:
        lines+=['',f"### {models[r['scenario']]} – {labels[r['direction']]}, Start {r['start']}",'','| Datum | Start | Hotelziel | Fortschritt | Fahrstrecke | Wasserzeit | Kreuzen² | Zusätzliches Warten unterwegs³ |','|---|---|---|---:|---:|---:|---:|---:|']
        for t in r['travel']:
            lines.append(f"| {t['date']} | {plan['spots'][t['start']]['name']} | {plan['spots'][t['end']]['name']} | {t['route_km']:.1f} km | {t['physical_km']:.1f} km | {t['water_hours']:.2f} h | {sum(l['upwind_seconds'] for l in t['legs'])/3600:.2f} h | {sum(l['land_wait_minutes'] for l in t['legs'][1:]):.0f} min |")
    lines+=['','² Teil der Wasserzeit, nicht zusätzlich. ³ Zusätzlich zu mindestens 25 Minuten pro Zwischenlandeplatz; Warten vor der ersten Tagesabfahrt ist hier nicht enthalten.','','## Umsetzung der Leistungsannahmen','','Grundlage: [Annahmen fürs Aufkreuzen](21-annahmen-aufkreuzen.md). Es wird keine konstante Geschwindigkeit von 25 km/h mehr verwendet.','','| Parameter | Basis | Vorsichtig |','|---|---|---|','| Amwindwinkel bei 12–<15 / 15–<20 / 20–25 kn | 60° / 55° / 55° | 65° / 60° / 60° |','| Fahrt auf Amwindschlägen | 16 / 20 / 18 km/h | 13,6 / 17 / 15,3 km/h |','| Geschwindigkeitsfaktor für Kreuzmanöver | 0,85 | 0,80 |','| Direkter Fortschritt gegen 15–<20 kn Wind | rund 9,8 km/h | rund 6,8 km/h |','| Andere fahrbare Kurse | Winkelabhängige Tabelle aus Annahmendokument | Dieselben Werte minus 15 % |','| Halsenkurse direkt nach Lee | 145° zur Wind-von-Richtung, Faktor 0,90 | Gleicher Winkel/Faktor; Geschwindigkeit minus 15 % |','','Zwischen den fahrbaren Stützpunkten wird nach Kurswinkel linear interpoliert. Die drei Windklassen werden wie vereinbart stufenweise verwendet. Innerhalb des Amwindsektors entstehen zwei symmetrische Kreuzschläge; bei Zielkursen tiefer als 145° zwei Halsenkurse. Die Schlaglängen werden so berechnet, dass ihre Summe genau den gewünschten Fortschritt ergibt. Die Manöverfaktoren werden einmal auf die Zeit angewendet, ohne zusätzliche doppelte Wendepauschale.','','Fünf Stunden Wasserzeit pro Tag bleiben die harte Grenze. Es gibt in diesem Vergleich keine zusätzliche 50-/75-/125-km-Tagesobergrenze: Die tatsächliche Fahrzeit bestimmt die mögliche Etappe. Hotelorte, Tagesfenster 09–17 Uhr Ortszeit, mindestens 25 Minuten Landpause je Zwischenlandeplatz und zusätzliche Wetter-Wartepausen bleiben gleich. Hotelöffnungen und Belegung sind nicht modelliert.','','## Kreuzschläge und Küste','','Die Route wird in lokale Fortschrittsstücke von höchstens 500 m und höchstens zwei Minuten Modellzeit aufgeteilt. Für jedes Stück werden die beiden möglichen Reihenfolgen der Kreuzschläge geprüft. Die Linien dürfen die vorhandene Landmaske mit 25 m Puffer nicht schneiden. Bei Platzmangel wird das Fortschrittsstück bis auf 25 m verkürzt; scheitern beide Reihenfolgen weiterhin, wird die betreffende Passage verworfen. Direkte Fahrstücke erhalten dieselbe Landprüfung.','','Diese Prüfung verhindert rechnerische Kreuzschläge durch Land. Sie sucht jedoch **keine grossräumige Ausweichroute weiter draussen**. Die kleinen Zickzacklinien sind eine lokale Näherung. Die pauschalen Manöververluste ersetzen eine genaue Simulation jeder Wende; sehr kurze Schläge können in Wirklichkeit ungünstiger sein. Der bisherige An-/Ablegezuschlag wird proportional auf Strecke und Zeit verteilt; exakte Strandmanöver sind damit nicht modelliert.','','## Wind und Zeitplanung','','Stündliche Windvektoren werden zeitlich linear interpoliert. Richtung und Leistung werden zu Beginn jedes höchstens zweiminütigen Fortschrittsstücks neu berechnet und für dessen Geometrie konstant gehalten. Die Windstärke wird zusätzlich an Anfang, Mitte und Ende jedes tatsächlichen Schlags zur jeweiligen Passagezeit geprüft. Hierfür wird der nächstgelegene der 91 vorhandenen Abfragepunkte verwendet; die räumliche Zuordnung wird auf einem 1-km-Gitter zwischengespeichert. Es werden keine neuen Wetterdaten erfunden oder nachgeladen.','','Die historische Rasterauflösung liegt nominell bei rund 9 km. Daher ist die Windprüfung auf den Kreuzschlägen keine ortsgenaue Messung. Richtungsänderungen innerhalb eines Rechenschritts und kleinere räumliche Effekte sind nur näherungsweise berücksichtigt. Wind muss während der verlängerten Passage zwischen 12 und 25 kn bleiben; alle Windrichtungen sind zulässig, aber nicht alle Zielkurse direkt fahrbar. Keine zusätzliche Böengrenze.','','Abfahrten an Land werden im Fünfminutenraster geprüft. Anders als im alten Modell bleiben mehrere Kombinationen aus Ankunftszeit und verbrauchter Wasserzeit erhalten: Früher anzukommen kann mehr Wasserzeit kosten. Der Planer prüft alle erreichbaren Hotelziele über die Tage, statt stets zum entferntesten Ziel zu fahren. Wetter ist rückblickend vollständig bekannt; dies ist keine Vorhersagesimulation.','','## Prüfung und Genauigkeit','']
    validation=json.loads((DATA/'tacking-validation.json').read_text());resolution=json.loads((DATA/'tacking-resolution-check.json').read_text())
    lines+=[f"{validation['runs']} Reisen geprüft; {validation['recorded_passages']} gespeicherte Teilfahrten entsprechen {validation['unique_passages_replayed']} unterschiedlichen Passagen, die erneut mit Wind- und Landprüfung gerechnet wurden. Kontrollen: Hotelnächte, Datum, Landpausen, Tageslicht, fünf Stunden Wasserzeit sowie Fahr- und Fortschrittsstrecke.", '', f"Zusätzlicher Auflösungstest: acht der längsten unterschiedlichen verwendeten Kreuzpassagen je Jahr und Modell, insgesamt {resolution['passages']}. Mit 60 statt 120 Sekunden Rechenschritt blieben {resolution['valid_at_60s']} fahrbar. Median der absoluten Fahrzeitänderung: {resolution['median_absolute_duration_change_percent']:.2f} %, Maximum: {resolution['max_absolute_duration_change_percent']:.2f} %. Das ist eine gezielte Stichprobe, kein vollständiger zweiter Reisevergleich und keine Bestätigung der angenommenen realen Fahrgeschwindigkeiten.",'','Unit-Tests prüfen die VMG-Zahlen, symmetrische Schlaggeometrie, Küstenhindernisse, Windverlust unterwegs, Wasserzeitlimit und das Beibehalten späterer Ankünfte mit geringerer Wasserzeit.','','## Einordnung','','Alle vier Kombinationen bleiben vor Abschluss der Runde stehen. Das bedeutet nicht, dass die reale Tour unmöglich ist. Es bedeutet, dass selbst mit Kreuzen und rückblickend optimaler Wahl unter diesen Zeit-, Wind-, Hotel- und lokalen Kursannahmen keine vollständige Reise entsteht. Das Basismodell und das vorsichtige Modell sind eine Bandbreite hypothetischer Leistungen; eigene GPS-Daten wären die Grundlage für eine persönliche Kalibrierung.','','Die Ergebnisse sind nicht direkt mit dem alten 360°-Modell bei konstant 25 km/h vergleichbar: Neben Fahrzeiten und Manövern ändern sich die lokalen Fahrtlinien, die räumliche Windzuordnung und die Auswahl zulässiger Tagesetappen.','','## Daten, Quellen und Reproduktion','','Windquelle: archivierte ECMWF-IFS-Daten der [Open-Meteo Historical Weather API](https://open-meteo.com/en/docs/historical-weather-api). [August-Datenbeschreibung](17-ab-august-180-grad.md), [ursprüngliche Winddaten](11-wind-api-und-daten.md), [Routen- und Küstenmethodik](09-methodik-und-daten.md), [Hotelquellen](13-variable-etappen-wartepausen.md), [Leistungsannahmen und deren Quellen](21-annahmen-aufkreuzen.md). Keine neuen API-Abfragen für diesen Lauf.','','```sh','python3 scripts/simulate_tacking.py','python3 scripts/validate_tacking.py','python3 scripts/check_tacking_resolution.py','python3 scripts/report_tacking.py',"python3 -m unittest discover -s scripts -p 'test_*.py'",'```','','- [Modellparameter](../data/phase2/tacking-model.json)', '- Jahresergebnisse: [2022](../data/phase2/tacking-2022.json), [2023](../data/phase2/tacking-2023.json), [2024](../data/phase2/tacking-2024.json), [2025](../data/phase2/tacking-2025.json). Je 244 Reisen mit Tageszielen, Teilfahrten, Kreuzzeit und Wasserzeit.', '- [Prüfergebnis](../data/phase2/tacking-validation.json) und [Auflösungstest](../data/phase2/tacking-resolution-check.json).','','Alle früheren Szenarien bleiben erhalten.']
    (ROOT/'docs/22-umrundung-mit-aufkreuzen.md').write_text('\n'.join(lines)+'\n')

if __name__=='__main__':main()
